local cases={};local function case(n,f)local ok,e=pcall(f);cases[#cases+1]={name=n,passed=ok,message=ok and"ok"or tostring(e)}end;local function eq(a,b)if a~=b then error(tostring(a).." ~= "..tostring(b),2)end end
local B=load_submission("lua/rhenium_contraption_blueprints/blueprints.lua");local function fresh(s)return assert(B.new({state=s}))end
local function graph(reverse)local e={{source_id="30",class="prop_physics",model="models/props_c17/oildrum001.mdl",pos={x=0,y=0,z=0},ang={x=0,y=0,z=0}},{source_id="10",class="prop_physics",model="models/props_c17/FurnitureChair001a.mdl",pos={x=40,y=0,z=0},ang={x=0,y=90,z=0}},{source_id="20",class="prop_physics",model="models/props_c17/FurnitureTable001a.mdl",pos={x=80,y=0,z=0},ang={x=0,y=0,z=0}}};if reverse then e={e[3],e[1],e[2]}end;return{entities=e,constraints={{type="Weld",a="30",b="10",params={}},{type="NoCollide",a="20",b="30",params={}}}}end
case("capture canonicalizes three nodes and two edges",function()local b=fresh();local ok,c,d=b:capture("r","A","build",1,graph());assert(ok,c);eq(d.entities,3);eq(d.constraints,2);local x=b:get("A","build");eq(x.schema.entities[1].id,"e1");eq(x.schema.constraints[1].id,"c1")end)
case("canonical hash ignores input table order",function()local a=fresh();local b=fresh();local _,_,x=a:capture("a","A","x",1,graph());local _,_,y=b:capture("b","A","x",1,graph(true));eq(x.hash,y.hash)end)
case("unsupported classes models and constraints fail",function()local b=fresh();local g=graph();g.entities[1].class="npc_citizen";local ok,c=b:capture("a","A","x",1,g);assert(not ok);eq(c,"unsupported_entity");g=graph();g.constraints[1].type="Rope";ok,c=b:capture("b","A","x",1,g);assert(not ok)end)
case("bad endpoints and self edges are rejected",function()local b=fresh();local g=graph();g.constraints[1].b="missing";local ok,c=b:capture("a","A","x",1,g);assert(not ok);eq(c,"invalid_endpoint");g=graph();g.constraints[1].b=g.constraints[1].a;ok,c=b:capture("b","A","x",1,g);assert(not ok)end)
case("nonfinite transforms are rejected before mutation",function()local b=fresh();local g=graph();g.entities[1].pos.x=0/0;local ok=b:capture("a","A","x",1,g);assert(not ok);eq(#b:list("A"),0)end)
case("entity constraint and blueprint budgets are enforced",function()local b=fresh();local g=graph();for i=1,14 do g.entities[#g.entities+1]={source_id="x"..i,class="prop_physics",model="models/props_c17/oildrum001.mdl",pos={x=i,y=0,z=0},ang={x=0,y=0,z=0}}end;local ok,c=b:capture("big","A","big",1,g);assert(not ok);eq(c,"invalid_graph");for i=1,8 do assert(b:capture("r"..i,"A","n"..i,1,graph()))end;ok,c=b:capture("nine","A","n9",1,graph());assert(not ok);eq(c,"blueprint_limit")end)
case("capture request replay and conflict are exact",function()local b=fresh();assert(b:capture("r","A","x",1,graph()));assert(b:capture("r","A","x",1,graph()));local ok,c=b:capture("r","A","y",1,graph());assert(not ok);eq(c,"request_conflict")end)
case("blueprint revision rejects stale replacement",function()local b=fresh();assert(b:capture("a","A","x",2,graph()));local ok,c=b:capture("b","A","x",1,graph());assert(not ok);eq(c,"stale_revision")end)
case("list and get are sorted detached owner views",function()local b=fresh();assert(b:capture("a","A","z",1,graph()));assert(b:capture("b","A","a",1,graph()));local x=b:list("A");eq(x[1].name,"a");local g=b:get("A","a");g.schema.entities[1].model="bad";assert(b:get("A","a").schema.entities[1].model~="bad");eq(#b:list("B"),0)end)
case("paste plan applies target transform to every node",function()local b=fresh();assert(b:capture("a","A","x",1,graph()));local ok,c,p=b:plan("p","A","x",1,{x=100,y=20,z=30});assert(ok,c);eq(p.entities[1].pos.x,140);eq(p.entities[1].pos.y,20);eq(p.entities[1].pos.z,30)end)
case("paste request replay revision and result are idempotent",function()local b=fresh();assert(b:capture("a","A","x",1,graph()));assert(b:plan("p","A","x",1,{x=1,y=2,z=3}));assert(b:plan("p","A","x",1,{x=1,y=2,z=3}));local ok,c=b:plan("q","A","x",2,{x=1,y=2,z=3});assert(not ok);eq(c,"stale_revision");assert(b:record_paste("p",{entities=3,constraints=2}));local _,code=b:record_paste("p",{entities=9,constraints=9});eq(code,"duplicate")end)
case("save load preserves schema hash requests and paste results",function()local b=fresh();local _,_,x=b:capture("a","A","x",1,graph());assert(b:plan("p","A","x",1,{x=0,y=0,z=0}));assert(b:record_paste("p",{entities=3,constraints=2}));local c=fresh(b:save());eq(c:get("A","x").schema.hash,x.hash);local ok,code=c:plan("p","A","x",1,{x=1,y=0,z=0});assert(not ok);eq(code,"request_conflict");assert(c:plan("p","A","x",1,{x=0,y=0,z=0}))end)
case("shutdown is idempotent and freezes capture",function()local b=fresh();assert(b:shutdown());assert(b:shutdown());local ok,c=b:capture("a","A","x",1,graph());assert(not ok);eq(c,"shutdown")end)
case("source identifiers require raw unique nonempty strings",function()for _,value in ipairs({false,7,""})do local b=fresh();local g=graph();g.entities[1].source_id=value;local ok,c=b:capture("bad"..tostring(value),"A","x",1,g);assert(not ok);eq(c,"unsupported_entity")end;local b=fresh();local g=graph();g.entities[2].source_id=g.entities[1].source_id;local ok,c=b:capture("duplicate","A","x",1,g);assert(not ok);eq(c,"unsupported_entity");g=graph();g.entities[1].source_id=nil;ok,c=b:capture("missing","A","x",1,g);assert(not ok);eq(c,"unsupported_entity")end)
case("malformed entity and constraint rows return stable errors",function()local b=fresh();local g=graph();g.entities[1]=false;local ok,c=b:capture("entity-row","A","x",1,g);assert(not ok);eq(c,"unsupported_entity");g=graph();g.constraints[1]=false;ok,c=b:capture("constraint-row","A","x",1,g);assert(not ok);eq(c,"invalid_endpoint")end)
case("constraint params are validated detached and included in hash",function()local a,b=fresh(),fresh();local g1,g2=graph(),graph();g1.constraints[1].params={Bone1=0,Bone2=1,forcelimit=5,nocollide=false};g2.constraints[1].params={Bone1=0,Bone2=1,forcelimit=6,nocollide=false};local _,_,x=a:capture("a","A","x",1,g1);local _,_,y=b:capture("b","A","x",1,g2);assert(x.hash~=y.hash);g1.constraints[1].params.Bone2=99;eq(a:get("A","x").schema.constraints[2].params.Bone2 or a:get("A","x").schema.constraints[1].params.Bone2,1);local bad=graph();bad.constraints[1].params={unknown=1};local ok,c=fresh():capture("bad","A","x",1,bad);assert(not ok);eq(c,"invalid_endpoint")end)
case("invalid plan identity name revision and target return stable public errors",function()local b=fresh();assert(b:capture("a","A","x",1,graph()));local ok,c=b:plan("p","bad id","x",1,{x=0,y=0,z=0});assert(not ok);eq(c,"invalid_request");ok,c=b:plan("q","A","bad name!",1,{x=0,y=0,z=0});assert(not ok);eq(c,"invalid_request");ok,c=b:plan("r","A","x",0,{x=0,y=0,z=0});assert(not ok);eq(c,"invalid_request");ok,c=b:plan("s","A","x",1,{x=0/0,y=0,z=0});assert(not ok);eq(c,"invalid_transform")end)
case("malformed persisted graphs hashes requests and paste rows are rejected",function()local b=fresh();assert(b:capture("a","A","x",1,graph()));assert(b:plan("p","A","x",1,{x=0,y=0,z=0}));assert(b:record_paste("p",{entities=3,constraints=2}));local variants={};local function add(change)local s=b:save();change(s);variants[#variants+1]=s end;add(function(s)if s.owners then s.owners.A.x.schema.hash="drift"else s.blueprints[1].schema.hash="drift"end end);add(function(s)if s.owners then s.owners.A.x.schema.constraints[1].params.Bone1=-1 else s.blueprints[1].schema.constraints[1].params.Bone1=-1 end end);add(function(s)if s.requests.a then s.requests.a.ok="yes"else s.requests[1].ok="yes"end end);add(function(s)if s.pastes.p then s.pastes.p.entities=-1 else s.pastes[1].result.entities=-1 end end);add(function(s)if s.blueprints then s.blueprints[2]=s.blueprints[1]else s.owners.A.x.revision=0 end end);for _,s in ipairs(variants)do local loaded,c=B.new({state=s});assert(loaded==nil);eq(c,"invalid_state")end end)
return{cases=cases}
